  7	import java.math.BigDecimal;
  8	import java.time.Instant;
  9	
 10	public class CheckoutService {
 11	    private static final Logger logger = LoggerFactory.getLogger(CheckoutService.class);
 12	    private final ProductRepository productRepo;
 13	    private final CustomerRepository customerRepo;
 14	    private final OrderRepository orderRepo;
 15	
 16	    public CheckoutService(ProductRepository productRepo, CustomerRepository customerRepo, OrderRepository orderRepo) {
 17	        this.productRepo = productRepo;
 18	        this.customerRepo = customerRepo;
 19	        this.orderRepo = orderRepo;
 20	    }
 21	
 22	    public Summary calculateSummary(CheckoutRequest req) {
 23	        BigDecimal subtotal = calculateSubtotal(req);
 24	
 25	        BigDecimal couponDiscount = calculateCouponDiscount(req, subtotal);
 26	
 27	        BigDecimal shippingCost = calculateShippingCost(req);
 28	        int deliveryDays = calculateDeliveryDays(req);
 29	
 30	        BigDecimal insurance = calculateInsurance(req, subtotal);
 31	
 32	        BigDecimal beforePayment = Money.add(Money.subtract(subtotal, couponDiscount), Money.add(shippingCost, insurance));
 33	
 34	        BigDecimal paymentAdjustment = calculatePaymentAdjustment(req, beforePayment);
 35	
 36	        BigDecimal finalTotal = Money.add(beforePayment, paymentAdjustment);
 37	
 38	        BigDecimal nextPurchaseCredit = calculateNextPurchaseCredit(req, subtotal);
 39	
 40	        boolean gift = shouldGetGift(req, subtotal);
 41	
 42	        int installments = req.getInstallmentsOrDefault();
 43	        BigDecimal installmentAmount = Money.divide(finalTotal, new BigDecimal(installments));
 44	
 45	        return new Summary(
 46	            subtotal,
 47	            couponDiscount,
 48	            shippingCost,
 49	            deliveryDays,
 50	            insurance,
 51	            paymentAdjustment,
 52	            finalTotal,
 53	            installments,
 54	            installmentAmount,
 55	            nextPurchaseCredit,
 56	            gift
 57	        );
 58	    }
 59	
 60	    private BigDecimal calculateSubtotal(CheckoutRequest req) {
 61	        BigDecimal subtotal = BigDecimal.ZERO;
 62	        for (OrderItem item : req.items()) {
 63	            Product product = productRepo.findBySku(item.sku());
 64	            if (product != null) {
 65	                subtotal = Money.add(subtotal, Money.multiply(product.price(), new BigDecimal(item.quantity())));
 66	            }
 67	        }
 68	        return subtotal;
 69	    }
 70	
 71	    private BigDecimal calculateCouponDiscount(CheckoutRequest req, BigDecimal subtotal) {
 72	        if (req.coupon() == null || req.coupon().isEmpty()) {
 73	            return BigDecimal.ZERO;
 74	        }
 75	
 76	        BigDecimal discount = switch (req.coupon()) {
 77	            case "WELCOME10" -> Money.multiply(subtotal, new BigDecimal("0.10"));
 78	            case "MINUS50" -> new BigDecimal("50.00");
 79	            case "FREESHIPPING" -> {
 80	                if (req.shippingMethod() == ShippingMethod.STORE_PICKUP) {
 81	                    yield BigDecimal.ZERO;
 82	                } else {
 83	                    yield calculateShippingCostRaw(req);
 84	                }
 85	            }
 86	            case "BUY3PAY2" -> calculateBuy3Pay2Discount(req);
 87	            default -> BigDecimal.ZERO;
 88	        };
 89	
 90	        BigDecimal max30Percent = Money.multiply(subtotal, new BigDecimal("0.30"));
 91	        return Money.min(discount, max30Percent);
 92	    }
 93	
 94	    private BigDecimal calculateBuy3Pay2Discount(CheckoutRequest req) {
 95	        BigDecimal totalDiscount = BigDecimal.ZERO;
 96	        for (OrderItem item : req.items()) {
 97	            if (item.quantity() >= 3) {
 98	                Product product = productRepo.findBySku(item.sku());
 99	                if (product != null) {
100	                    int freeUnits = item.quantity() / 3;
101	                    totalDiscount = Money.add(totalDiscount, Money.multiply(product.price(), new BigDecimal(freeUnits)));
102	                }
103	            }
104	        }
105	        return totalDiscount;
106	    }
107	
108	    private BigDecimal calculateShippingCost(CheckoutRequest req) {
109	        if (req.clubTier() == ClubTier.GOLD && req.shippingMethod() != ShippingMethod.COURIER) {
110	            return BigDecimal.ZERO;
111	        }
112	        return calculateShippingCostRaw(req);
113	    }
114	
115	    private BigDecimal calculateShippingCostRaw(CheckoutRequest req) {
116	        return switch (req.shippingMethod()) {
117	            case STORE_PICKUP -> BigDecimal.ZERO;
118	            case COURIER -> new BigDecimal("18.00");
119	            case ECONOMY, EXPRESS -> {
120	                try {
121	                    double totalWeightKg = calculateTotalWeight(req);
122	                    String service = req.shippingMethod() == ShippingMethod.ECONOMY ? "STD" : "EXP";
123	                    var quote = TransLogClient.quote(req.zipCode(), totalWeightKg, service);
124	                    if (quote != null) {
125	                        yield quote.price();
126	                    }
127	                    yield BigDecimal.ZERO;
128	                } catch (TransLogClient.CarrierUnavailableException e) {
129	                    yield BigDecimal.ZERO;
130	                }
131	            }
132	        };
133	    }
134	
135	    private int calculateDeliveryDays(CheckoutRequest req) {
136	        int baseDays = switch (req.shippingMethod()) {
137	            case STORE_PICKUP -> 1;
138	            case COURIER -> 0;
139	            case ECONOMY, EXPRESS -> {
140	                try {
141	                    double totalWeightKg = calculateTotalWeight(req);
142	                    String service = req.shippingMethod() == ShippingMethod.ECONOMY ? "STD" : "EXP";
143	                    var quote = TransLogClient.quote(req.zipCode(), totalWeightKg, service);
144	                    if (quote != null) {
145	                        yield quote.deliveryDays();
146	                    }
147	                    yield 0;
148	                } catch (TransLogClient.CarrierUnavailableException e) {
149	                    yield 0;
150	                }
151	            }
152	        };
153	        return baseDays + req.region().getExtraDeliveryDays();
154	    }
155	
156	    private double calculateTotalWeight(CheckoutRequest req) {
157	        double total = 0;
158	        for (OrderItem item : req.items()) {
159	            Product product = productRepo.findBySku(item.sku());
160	            if (product != null) {
161	                total += product.weightKg().doubleValue() * item.quantity();
162	            }
163	        }
164	        return total;
165	    }
166	
167	    private BigDecimal calculateInsurance(CheckoutRequest req, BigDecimal subtotal) {
168	        BigDecimal percentage = req.region().insuranceRate;
169	        BigDecimal insurance = Money.multiply(subtotal, percentage);
170	
171	        if (req.region().insuranceLimit != null) {
172	            insurance = Money.min(insurance, req.region().insuranceLimit);
173	        }
174	
175	        return insurance;
 55	        }
 56	
 57	        if (req.zipCode() == null || !ZIP_PATTERN.matcher(req.zipCode()).matches()) {
 58	            return new ValidationError("INVALID_ZIP_CODE", 422);
 59	        }
 60	
 61	        if (req.shippingMethod() == null) {
 62	            return new ValidationError("INVALID_SHIPPING_METHOD", 422);
 63	        }
 64	
 65	        double totalWeightKg = calculateTotalWeight(req.items(), products);
 66	        if (req.shippingMethod() == ShippingMethod.COURIER && totalWeightKg > 5) {
 67	            return new ValidationError("SHIPPING_METHOD_UNAVAILABLE", 422);
 68	        }
 69	
 70	        if (req.shippingMethod() == ShippingMethod.ECONOMY || req.shippingMethod() == ShippingMethod.EXPRESS) {
 71	            try {
 72	                String service = req.shippingMethod() == ShippingMethod.ECONOMY ? "STD" : "EXP";
 73	                var quote = TransLogClient.quote(req.zipCode(), totalWeightKg, service);
 74	                if (quote == null) {
 75	                    return new ValidationError("SHIPPING_METHOD_UNAVAILABLE", 422);
 76	                }
 77	            } catch (TransLogClient.CarrierUnavailableException e) {
 78	                return new ValidationError("CARRIER_UNAVAILABLE", 503);
 79	            }
 80	        }
 81	
